roup,\'-\',replen_size) as sku_map_replen, pareto, sku_class from snitch_db.maplemonk.store_replen_2_May2025 where xl5_alloc>0 group by branch_code, sku_group, priority, final_action, product_name, availability_category, replen_units, sku_map_replen, pareto, sku_class UNION select branch_code, sku_group, priority, final_action, product_name, availability_category, xl6_alloc as replen_units, \'6XL\' as replen_size, concat(sku_group,\'-\',replen_size) as sku_map_replen, pareto, sku_class from snitch_db.maplemonk.store_replen_2_May2025 where xl6_alloc>0 group by branch_code, sku_group, priority, final_action, product_name, availability_category, replen_units, sku_map_replen, pareto, sku_class UNION select branch_code, sku_group, priority, final_action, product_name, availability_category, xl6_alloc as replen_units, \'7XL\' as replen_size, concat(sku_group,\'-\',replen_size) as sku_map_replen, pareto, sku_class from snitch_db.maplemonk.store_replen_2_May2025 where xl6_alloc>0 group by branch_code, sku_group, priority, final_action, product_name, availability_category, replen_units, sku_map_replen, pareto, sku_class UNION select branch_code, sku_group, priority, final_action, product_name, availability_category, xl6_alloc as replen_units, \'8XL\' as replen_size, concat(sku_group,\'-\',replen_size) as sku_map_replen, pareto, sku_class from snitch_db.maplemonk.store_replen_2_May2025 where xl6_alloc>0 group by branch_code, sku_group, priority, final_action, product_name, availability_category, replen_units, sku_map_replen, pareto, sku_class UNION select branch_code, sku_group, priority, final_action, product_name, availability_category, xl6_alloc as replen_units, \'NA\' as replen_size, sku_group as sku_map_replen, pareto, sku_class from snitch_db.maplemonk.store_replen_2_May2025 where xl6_alloc>0 group by branch_code, sku_group, priority, final_action, product_name, availability_category, replen_units, sku_map_replen, pareto, sku_class order by priority, pareto, replen_units desc ), sku_map as ( select sku_code, REVERSE(SUBSTRING(REVERSE(sku_code), 1, POSITION(\'-\', REVERSE(sku_code)) - 1)) AS size, CASE WHEN sku_code LIKE \'SH%\' THEN CASE WHEN size = \'39\' THEN \'XS\' WHEN size = \'40\' THEN \'S\' WHEN size = \'41\' THEN \'M\' WHEN size = \'42\' THEN \'L\' WHEN size = \'43\' THEN \'XL\' WHEN size = \'44\' THEN \'XXL\' WHEN size = \'45\' THEN \'3XL\' ELSE size END WHEN sku_code LIKE \'SN%\' or sku_code LIKE \'BP%\' THEN \'NA\' ELSE CASE WHEN size = \'28\' THEN \'XS\' WHEN size = \'30\' THEN \'S\' WHEN size = \'32\' THEN \'M\' WHEN size = \'34\' THEN \'L\' WHEN size = \'36\' THEN \'XL\' WHEN size = \'38\' THEN \'XXL\' WHEN size = \'40\' THEN \'3XL\' WHEN size = \'42\' THEN \'4XL\' WHEN size = \'44\' THEN \'5XL\' WHEN size = \'46\' THEN \'6XL\' WHEN size = \'48\' THEN \'7XL\' WHEN size = \'50\' THEN \'8XL\' WHEN size = \'\' THEN \'NA\' WHEN size IS NULL THEN \'NA\' ELSE size END END AS size_map, REVERSE(SUBSTRING(REVERSE(sku_code), CHARINDEX(\'-\', REVERSE(sku_code)) + 1)) AS sku_group, concat(sku_group,\'-\',size_map) as sku_map from ( select sku as sku_code from snitch_db.maplemonk.inventory_aging_buckets_snitch union select logicusercode as sku_code from snitch_db.maplemonk.logicerp23_24_get_stock_in_hand union select sku as sku_code from snitch_db.maplemonk.STORE_fact_items_offline union select sku as sku_code from snitch_db.snitch.product_dim group by sku_code ) ) select replen_db.*, sku_map.sku_code, SUM(replen_units) OVER (PARTITION BY sku_code ORDER BY sku_code,priority,pareto) AS cuml_replen_units from replen_db left join sku_map on replen_db.sku_map_replen=sku_map.sku_map order by sku_code,priority, pareto ) ), Jit AS ( SELECT \"ITEM CODE\", BRANCH_CODE, STORE, SUM(qty) AS qty FROM SNITCH_DB.MAPLEMONK.JIT_OFFLINE_GOODS GROUP BY 1, 2, 3 ) SELECT a.*, b.qty FROM Overall a LEFT JOIN Jit b ON a.SKU_CODE = b.\"ITEM CODE\" AND a.BRANCH_CODE = b.BRANCH_CODE ) where ifnull(REPLEN_UNITS,0) - ifnull(qty,0) >0 ORDER BY SKU_CODE, PRIORITY, PARETO; ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; create or replace table snitch_db.maplemonk.SRU_RPL_3_MARCH_26 as WITH schedule_rpl_raw AS ( SELECT branch_code, zone, UPPER(LEFT( CASE WHEN UPPER(cluster) IN (\'BANGALORE\', \'KARNATAKA\') AND UPPER(LEFT(south_rpl, 3)) = \'WED\' THEN \'TUE\' WHEN zone = \'South\' THEN south_rpl ELSE north_rpl END, 3 )) AS rpl_order_day FROM ( SELECT *, ROW_NUMBER() OVER ( PARTITION BY branch_code ORDER BY branch_code ) AS rn FROM snitch_db.maplemonk.store_category_delta ) t WHERE rn = 1 ), schedule_rpl AS ( SELECT branch_code, rpl_order_day, zone FROM schedule_rpl_raw QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code ORDER BY rpl_order_day ) = 1 ), exclude_skus AS ( SELECT \"Branch code\" as branch_code, UPPER(\"SKU GROUP\") AS sku_group FROM snitch_db.maplemonk.EXCLUDE_LIST QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code, UPPER(\"SKU GROUP\") ORDER BY branch_code ) = 1 ), final_discount_skus as ( select distinct UPPER(\"SKU Group\") AS sku_group from snitch_db.maplemonk.final_discount_skus_sheet1 where upper(category) not like \'%COLLECTION%\' ), RPL_1 AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.SRU_RPL_1_MARCH_26 QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code, sku_group ORDER BY branch_code, sku_group ) = 1 ), RPL_2 AS ( SELECT * FROM SNITCH_DB.MAPLEMONK.SRU_RPL_2_MARCH_26 WHERE replen_remarks in (\'replen, high str\', \'core_sku, replen\') QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code, sku_group ORDER BY branch_code, sku_group ) = 1 ), FINAL_SKU_POOL AS ( SELECT A.*, B.REPLEN_REMARKS, B.AVG_SKU_SELL_THRU, C.RPL_ORDER_DAY, C.ZONE FROM RPL_1 A INNER JOIN RPL_2 B ON A.BRANCH_CODE = B.BRANCH_CODE AND UPPER(A.SKU_GROUP) = UPPER(B.SKU_GROUP) INNER JOIN schedule_rpl C ON A.BRANCH_CODE = C.BRANCH_CODE AND UPPER(TRIM(C.RPL_ORDER_DAY)) = upper(DAYNAME(CURRENT_DATE)) LEFT JOIN exclude_skus ex ON A.branch_code = ex.branch_code AND UPPER(A.sku_group) = ex.sku_group LEFT JOIN final_discount_skus fd on a.sku_group = fd.sku_group where fd.sku_group is null and ex.branch_code IS NULL ), thresholds AS ( SELECT category, 1 AS TH_XS, CASE WHEN category IN (\'Cargo Pants\',\'Jeans\',\'Trousers\', \'Joggers & Trackpants\', \'Shorts\') THEN 4 ELSE 3 END AS TH_S, CASE WHEN category IN (\'Cargo Pants\',\'Jeans\',\'Trousers\',\'Joggers & Trackpants\', \'Shorts\') THEN 5 ELSE 4 END AS TH_M, CASE WHEN category IN (\'Cargo Pants\',\'Jeans\',\'Trousers\',\'Joggers & Trackpants\', \'Shorts\') THEN 5 ELSE 4 END AS TH_L, CASE WHEN category IN (\'Cargo Pants\',\'Jeans\',\'Trousers\',\'Joggers & Trackpants\', \'Shorts\') THEN 4 ELSE 3 END AS TH_XL, 1 AS TH_XXL, 3 AS TH_3XL, 3 AS TH_4XL, 3 AS TH_5XL, 3 AS TH_6XL FROM FINAL_SKU_POOL GROUP BY category ), REPLEN_UNITS AS ( SELECT F.*, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XS_60,0) - (COALESCE(F.INV_XS,0) + COALESCE(F.JIT_XS,0)) ) > 0 THEN GREATEST( T.TH_XS, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XS_60,0) - (COALESCE(F.INV_XS,0) + COALESCE(F.JIT_XS,0)) ) ELSE 0 END AS RPL_UNITS_XS, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_S_60,0) - (COALESCE(F.INV_S,0) + COALESCE(F.JIT_S,0)) ) > 0 THEN GREATEST( T.TH_S, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_S_60,0) - (COALESCE(F.INV_S,0) + COALESCE(F.JIT_S,0)) ) ELSE 0 END AS RPL_UNITS_S, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_M_60,0) - (COALESCE(F.INV_M,0) + COALESCE(F.JIT_M,0)) ) > 0 THEN GREATEST( T.TH_M, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_M_60,0) - (COALESCE(F.INV_M,0) + COALESCE(F.JIT_M,0)) ) ELSE 0 END AS RPL_UNITS_M, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_L_60,0) - (COALESCE(F.INV_L,0) + COALESCE(F.JIT_L,0)) ) > 0 THEN GREATEST( T.TH_L, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_L_60,0) - (COALESCE(F.INV_L,0) + COALESCE(F.JIT_L,0)) ) ELSE 0 END AS RPL_UNITS_L, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XL_60,0) - (COALESCE(F.INV_XL,0) + COALESCE(F.JIT_XL,0)) ) > 0 THEN GREATEST( T.TH_XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XL_60,0) - (COALESCE(F.INV_XL,0) + COALESCE(F.JIT_XL,0)) ) ELSE 0 END AS RPL_UNITS_XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XXL_60,0) - (COALESCE(F.INV_XXL,0) + COALESCE(F.JIT_XXL,0)) ) > 0 THEN GREATEST( T.TH_XXL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_XXL_60,0) - (COALESCE(F.INV_XXL,0) + COALESCE(F.JIT_XXL,0)) ) ELSE 0 END AS RPL_UNITS_XXL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_3XL_60,0) - (COALESCE(F.INV_3XL,0) + COALESCE(F.JIT_3XL,0)) ) > 0 THEN GREATEST( T.TH_3XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_3XL_60,0) - (COALESCE(F.INV_3XL,0) + COALESCE(F.JIT_3XL,0)) ) ELSE 0 END AS RPL_UNITS_3XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_4XL_60,0) - (COALESCE(F.INV_4XL,0) + COALESCE(F.JIT_4XL,0)) ) > 0 THEN GREATEST( T.TH_4XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_4XL_60,0) - (COALESCE(F.INV_4XL,0) + COALESCE(F.JIT_4XL,0)) ) ELSE 0 END AS RPL_UNITS_4XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_5XL_60,0) - (COALESCE(F.INV_5XL,0) + COALESCE(F.JIT_5XL,0)) ) > 0 THEN GREATEST( T.TH_5XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_5XL_60,0) - (COALESCE(F.INV_5XL,0) + COALESCE(F.JIT_5XL,0)) ) ELSE 0 END AS RPL_UNITS_5XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_6XL_60,0) - (COALESCE(F.INV_6XL,0) + COALESCE(F.JIT_6XL,0)) ) > 0 THEN GREATEST( T.TH_6XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_6XL_60,0) - (COALESCE(F.INV_6XL,0) + COALESCE(F.JIT_6XL,0)) ) ELSE 0 END AS RPL_UNITS_6XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_7XL_60,0) - (COALESCE(F.INV_7XL,0) + COALESCE(F.JIT_7XL,0)) ) > 0 THEN GREATEST( T.TH_6XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_7XL_60,0) - (COALESCE(F.INV_7XL,0) + COALESCE(F.JIT_7XL,0)) ) ELSE 0 END AS RPL_UNITS_7XL, CASE WHEN ( (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_8XL_60,0) - (COALESCE(F.INV_8XL,0) + COALESCE(F.JIT_8XL,0)) ) > 0 THEN GREATEST( T.TH_6XL, (COALESCE(F.ROS,0) * 7) * COALESCE(F.RATIO_8XL_60,0) - (COALESCE(F.INV_8XL,0) + COALESCE(F.JIT_8XL,0)) ) ELSE 0 END AS RPL_UNITS_8XL FROM FINAL_SKU_POOL F LEFT JOIN thresholds T ON F.category = T.category ), ideal_options AS ( SELECT branch_code, category, MAX(ideal_option_count) AS ideal_option_count, MAX(full_only_options) AS full_only_options, GREATEST((ROUND(MAX(ideal_option_count) * 0.85, 0) - MAX(full_only_options)), 0) AS delta_options FROM snitch_db.maplemonk.outward_options_offline GROUP BY 1,2 ), cut_sizes AS ( SELECT branch_code, category, COALESCE(SUM(CUT_SIZE_SKUS) / NULLIF(SUM(TOTAL_SKUS), 0), 0) as cut_size_new_with_jit_pt FROM snitch_db.maplemonk.store_category_delta GROUP BY 1,2 ), ideal_and_cut_size AS ( SELECT ru.*, id.ideal_option_count, id.full_only_options, id.delta_options, cs.cut_size_new_with_jit_pt FROM REPLEN_UNITS ru LEFT JOIN ideal_options id ON ru.branch_code = id.branch_code AND ru.category = id.category LEFT JOIN cut_sizes cs ON ru.branch_code = cs.branch_code AND ru.category = cs.category ), store_category_inputs AS ( SELECT branch_code, category, zone, MAX(delta_options) AS delta_options, MAX(cut_size_new_with_jit_pt) AS cut_size_new_with_jit_pt FROM ideal_and_cut_size GROUP BY 1,2,3 ), ranked_store_category AS ( SELECT branch_code, category, zone, ROW_NUMBER() OVER ( PARTITION BY zone, category ORDER BY delta_options DESC, cut_size_new_with_jit_pt DESC, branch_code ) AS final_rank FROM store_category_inputs ), final_sku_pool_with_replen_units AS ( SELECT fsp.*, ru.RPL_UNITS_XS, ru.RPL_UNITS_S, ru.RPL_UNITS_M, ru.RPL_UNITS_L, ru.RPL_UNITS_XL, ru.RPL_UNITS_XXL, ru.RPL_UNITS_3XL, ru.RPL_UNITS_4XL, ru.RPL_UNITS_5XL, ru.RPL_UNITS_6XL, ru.RPL_UNITS_7XL, ru.RPL_UNITS_8XL FROM FINAL_SKU_POOL fsp LEFT JOIN ( SELECT * FROM REPLEN_UNITS QUALIFY ROW_NUMBER() OVER ( PARTITION BY branch_code, sku_group ORDER BY branch_code, sku_group ) = 1 ) ru ON fsp.branch_code = ru.branch_code AND fsp.sku_group = ru.sku_group ), final_pool AS ( SELECT e.*, rsc.final_rank FROM final_sku_pool_with_replen_units e INNER JOIN ranked_store_category rsc ON e.branch_code = rsc.branch_code AND e.category = rsc.category AND e.zone = rsc.zone ) SELECT * FROM final_pool;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
